-- Covering index: key columns for lookup, INCLUDE columns ride along
-- Enables Index Only Scan and avoids heap fetches
CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} ({{key_col}})
  INCLUDE ({{include_col_a}}, {{include_col_b}});

-- Keep visibility map fresh so Index Only Scan can skip heap
VACUUM (ANALYZE) {{table_name}};

EXPLAIN (ANALYZE, BUFFERS)
SELECT {{key_col}}, {{include_col_a}}, {{include_col_b}}
FROM {{table_name}}
WHERE {{key_col}} = $1;
-- Look for: Index Only Scan, Heap Fetches: 0
